using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class ReleaseCandidateSummaryFileStore{private readonly string _path;public ReleaseCandidateSummaryFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(ReleaseCandidateSummary value){if(value.LiveAuthorityEnabled)throw new InvalidOperationException("Release candidate summary cannot grant live authority.");Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public ReleaseCandidateSummary Load(){var v=JsonSerializer.Deserialize<ReleaseCandidateSummary>(File.ReadAllText(_path))??throw new InvalidOperationException("Release candidate summary JSON is invalid.");if(v.LiveAuthorityEnabled)throw new InvalidOperationException("Persisted release candidate grants live authority.");return v;}}
